  if get(a,"normalized")!=&Null&&!matches!(get(a,"normalized"),Bool(_)){return Err("Scene normalized flag must be boolean".into());}let normalized=boolean(a,"normalized");if normalized&&!matches!(kind,5120|5121|5122|5123){return Err("Scene accessor normalization is invalid".into());}
