  if get(p,"targets")!=&Null&&!get(p,"targets").array()?.is_empty(){return Err("Morph-target scenes require a different preview renderer; export remains available".into());}let mode=optional(p,"mode",4)?;if !matches!(mode,4|5|6){return Err("Scene preview requires triangle, strip or fan geometry; export remains available".into());}
  let pos=reader.accessor(index(get(get(p,"attributes"),"POSITION"))?,reader.vertices)?;if pos.dim!=3||pos.component!=5126||pos.normalized{return Err("Scene positions must be unnormalized float VEC3".into());}
