  let ids=if get(p,"indices")==&Null{(0..pos.rows.len()).collect::<Vec<_>>()}else{let v=reader.accessor(index(get(p,"indices"))?,reader.triangles*3)?;if v.dim!=1||v.normalized||!matches!(v.component,5121|5123|5125){return Err("Scene triangle indices must be unsigned scalar values".into());}v.rows.iter().map(|r|r[0]as usize).collect()};if ids.iter().any(|i|*i>=pos.rows.len())||ids.len()<3||(mode==4&&ids.len()%3!=0){return Err("Scene triangle indices exceed positions or are incomplete".into());}
  let count=if mode==4{ids.len()/3}else{ids.len()-2};if count>reader.triangles.saturating_sub(out.len()){return Err("Scene geometry exceeds the interactive preview triangle bound; export remains available".into());}
