 for root in roots{node(&mut reader,root,identity(),&mut visited,0,&mut triangles)?;}if triangles.is_empty(){return Err("Scene contains no previewable triangle geometry".into());}
 let mut min=[f64::INFINITY;3];let mut max=[f64::NEG_INFINITY;3];for t in &triangles{for p in t.points{for k in 0..3{min[k]=min[k].min(p[k]);max[k]=max[k].max(p[k]);}}}let center=std::array::from_fn::<_,3,_>(|k|min[k]/2.+max[k]/2.);let radius=(0..3).map(|k|(max[k]-center[k]).abs()).fold(0.,f64::max);if !radius.is_finite()||radius<=0.{return Err("Scene geometry has no finite spatial extent".into());}
